<script setup>
import { onMounted, reactive, ref } from 'vue';
import { api } from '../../services/api.js';
import { workspace, loadStores } from '../../services/workspace.js';
import { notify } from '../../services/notifications.js';
import Icon from '../../components/Icon.vue';

const loading=ref(true),saving=ref(false),uploading=ref(false),error=ref('');
const form=reactive({name:'',iconUrl:'',icon192Url:'',manifestUrl:''});
async function load(){loading.value=true;error.value='';try{Object.assign(form,await api.get(`/stores/${workspace.activeStoreId}/pwa`))}catch(e){error.value=e.message}finally{loading.value=false}}
onMounted(load);
async function uploadIcon(event){const file=event.target.files?.[0];event.target.value='';if(!file)return;uploading.value=true;try{const body=new FormData();body.append('purpose','pwa-icon');body.append('files',file);const items=await api.upload(`/stores/${workspace.activeStoreId}/uploads`,body);const small=items.find(item=>item.width===192),large=items.find(item=>item.width===512);if(!small||!large)throw new Error('No se pudieron generar todos los tamaños del ícono.');form.icon192Url=small.url;form.iconUrl=large.url;notify.success('Ícono preparado. Guardá los cambios para aplicarlo.')}catch(e){notify.error(e.message)}finally{uploading.value=false}}
async function save(){saving.value=true;error.value='';try{Object.assign(form,await api.put(`/stores/${workspace.activeStoreId}/pwa`,{name:form.name,iconUrl:form.iconUrl,icon192Url:form.icon192Url}));await loadStores();notify.success('Aplicación PWA actualizada.')}catch(e){error.value=e.message;notify.error(e.message)}finally{saving.value=false}}
function removeIcon(){form.iconUrl='';form.icon192Url=''}
</script>

<template><div><header class="p-page-header"><div><p class="p-eyebrow">TU TIENDA</p><h1>Aplicación PWA</h1><p>Definí cómo se verá esta tienda cuando un cliente la instale en su celular o computadora.</p></div></header><div v-if="error" class="p-error">{{error}}</div><div v-if="loading" class="p-loading-page"><span class="p-spinner"/></div><form v-else class="p-form" @submit.prevent="save"><section class="p-section-card"><div class="p-section-title"><div><h2>Identidad de la aplicación</h2><p>El nombre y el ícono son independientes para cada tienda.</p></div><Icon name="phone"/></div><div class="p-form-grid"><div class="p-field full"><label for="pwa-name">Nombre de la aplicación</label><input id="pwa-name" v-model.trim="form.name" required maxlength="120" placeholder="Nombre de tu tienda"/><small>Es el nombre que verá el cliente al instalar la tienda.</small></div><div class="p-field full"><label>Ícono</label><div class="pwa-icon-editor"><div class="pwa-icon-preview"><img v-if="form.iconUrl" :src="form.iconUrl" alt="Vista previa del ícono PWA"/><Icon v-else name="store" :size="42"/></div><div><label class="btn btn-secondary pwa-upload" :class="{disabled:uploading}"><input type="file" accept="image/png,image/jpeg,image/webp" :disabled="uploading" @change="uploadIcon"/>{{uploading?'Procesando…':'Subir ícono'}}</label><button v-if="form.iconUrl" type="button" class="btn btn-text" @click="removeIcon">Quitar ícono</button><small>Usá una imagen cuadrada de al menos 192 × 192 px. Se generan automáticamente versiones PNG de 192 y 512 px.</small></div></div></div></div></section><section class="p-section-card"><div class="p-section-title"><div><h2>Instalación</h2><p>La tienda publica automáticamente su manifest según el dominio desde el que se visita.</p></div></div><div class="p-info"><strong>{{form.name||'Tu tienda'}}</strong><br/>Cuando el navegador permita instalarla, el cliente verá este nombre y el ícono configurado arriba. En dominio propio o subdominio la aplicación abre en <code>/</code>; usando el enlace clásico abre en <code>/t/{{workspace.stores.find(item=>item._id===workspace.activeStoreId)?.slug}}/</code>.</div></section><footer class="p-form-footer"><small>Los cambios se aplican a nuevas instalaciones y a la actualización del manifest.</small><div class="p-form-actions"><button class="btn btn-primary" :disabled="saving||uploading">{{saving?'Guardando…':'Guardar PWA'}}</button></div></footer></form></div></template>

<style scoped>
.pwa-icon-editor{display:flex;align-items:center;gap:18px}.pwa-icon-preview{width:112px;height:112px;border:1px solid var(--line);border-radius:22px;background:var(--surface-alt);display:grid;place-items:center;overflow:hidden;flex:none}.pwa-icon-preview img{width:100%;height:100%;object-fit:cover}.pwa-icon-editor>div:last-child{display:flex;align-items:flex-start;flex-wrap:wrap;gap:10px}.pwa-icon-editor small{width:100%;color:var(--muted)}.pwa-upload{position:relative;overflow:hidden}.pwa-upload input{position:absolute;inset:0;opacity:0;cursor:pointer}.pwa-upload.disabled{opacity:.55;pointer-events:none}@media(max-width:600px){.pwa-icon-editor{align-items:flex-start;flex-direction:column}}
</style>
